/**
 * On-the-job tasks (FEEDBACK_NOTE, work.ts): the work your manager hands you
 * once you hold a professional job. Eight per profession, each with four
 * options, the best one, and a one-line why for every option, in English
 * and French (like the quiz bank: proper names and code stay the same).
 *
 * Row: [profession, id, title, French title, question, [four options],
 * best index, [four whys], French question, [French options], [French
 * whys], code?]. The code, when there is one, is shown as written.
 */
import type { ProfessionId } from './professions.js';

export interface JobTask {
  id: string;
  profession: ProfessionId;
  /** What kind of work it is ("Code review"). */
  title: string;
  text: string;
  options: string[];
  best: number;
  /** Why each option is (or isn't) the call, one line each. */
  why: string[];
  /** A snippet to read (code reviews), shown as written. */
  code?: string;
  fr: { title: string; text: string; options: string[]; why: string[] };
}

type Row = [
  ProfessionId,
  string,
  string,
  string,
  string,
  string[],
  number,
  string[],
  string,
  string[],
  string[],
  string?,
];

const REFUND = `async function refund(id, amount) {
  const p = await db.payment(id)
  db.balance += amount   // no check
  await bank.send(p.card, amount)
  return 'ok'
}`;

const LOGIN = `const user = await db.query(
  "SELECT * FROM users WHERE email = '" + email + "'"
)`;

