/**
 * Where the best option sits: the rows are written with it anywhere, and
 * each task's four options are rotated (all four lists together) so the best
 * one lands on A, B, C or D in turn.
 */
const slotOf = (i: number) => (i * 3 + 1) % 4;
const rotate = <T>(xs: T[], shift: number): T[] =>
  xs.map((_, k) => xs[(k - shift + xs.length * 2) % xs.length]!);

export const JOB_TASKS: readonly JobTask[] = ROWS.map(
  (
    [profession, id, title, frTitle, text, options, best, why, frText, frOptions, frWhy, code],
    i,
  ) => {
    const shift = (slotOf(i) - best + 4) % 4;
    return {
      id,
      profession,
      title,
      text,
      options: rotate(options, shift),
      best: (best + shift) % 4,
      why: rotate(why, shift),
      ...(code ? { code } : {}),
      fr: {
        title: frTitle,
        text: frText,
        options: rotate(frOptions, shift),
        why: rotate(frWhy, shift),
      },
    };
  },
);

const BY_ID = new Map(JOB_TASKS.map((t) => [t.id, t]));
export const jobTaskById = (id: string): JobTask | undefined => BY_ID.get(id);
export const jobTasksOf = (profession: string): JobTask[] =>
  JOB_TASKS.filter((t) => t.profession === profession);
